/**
 * Relayer Module (V2 API).
 *
 * @remarks
 * This module provides the `getUmbraRelayer` factory for creating relayer instances
 * that interact with the Umbra relayer's V2 API. The relayer builds, signs, and
 * submits claim transactions on behalf of users.
 *
 * **What is the Relayer?**
 * The Umbra relayer is a semi-trusted intermediary that submits privacy-preserving
 * transactions on behalf of users. It receives cryptographic data (ZK proofs,
 * nullifiers, linker encryptions) and builds all Solana transactions server-side.
 *
 * **Trust Model (Semi-Trusted):**
 * The relayer is SEMI-TRUSTED. It can observe transaction contents (amounts,
 * mints, timing) because it must broadcast them. However, it CANNOT:
 * - Steal funds — ZK proofs and nullifier commitments prevent double-spending
 * - Forge signatures — Transactions use cryptographic commitments verified on-chain
 * - Link sender to recipient — Merkle commitments and ZK proofs sever that link
 *
 * **API Endpoints Used:**
 * - `GET /v1/relayer/info` — Get relayer address, supported mints, active pools
 * - `POST /v1/claims` — Submit a claim request (relayer builds transactions)
 * - `GET /v1/claims/{id}` — Poll claim status
 *
 * @packageDocumentation
 */

import { address, type Address } from "@solana/kit";
import type { U32 } from "../types";
import type {
  IUmbraRelayer,
  GetUmbraRelayerArgs,
  GetUmbraRelayerDeps,
  SupportedMintsResponse,
  ClaimRequest,
  ClaimSubmitResponse,
  ClaimStatusResponse,
  ClaimStatus,
  ClaimBatchResult,
} from "./interfaces";

// ============================================================================
// Constants
// ============================================================================

/**
 * Canonical endpoint paths for all relayer API operations.
 * @internal
 */
const ENDPOINTS = {
  /** Fetches relayer address, supported mints, and active stealth pool indices. */
  RELAYER_INFO: `/v1/relayer/info`,
  /** Submits a claim request (relayer builds transactions from crypto data). */
  CLAIM_SUBMIT: `/v1/claims`,
  /** Polls claim status by request ID. `{id}` is replaced at call time. */
  CLAIM_STATUS: `/v1/claims/{id}`,
} as const;

// ============================================================================
// Error Class
// ============================================================================

/**
 * Error class for relayer-related failures.
 *
 * @remarks
 * Thrown when relayer API calls fail due to network issues, invalid responses,
 * transaction rejections, or server errors. Provides structured fields for
 * programmatic error handling.
 *
 * @public
 */
export class RelayerError extends Error {
  /** The relayer operation that failed (e.g. `"getRelayerAddress"`, `"claimSubmit"`). */
  public readonly operation: string;
  /** HTTP status code if the server responded, `undefined` for transport errors. */
  public readonly statusCode: number | undefined;
  /** Machine-readable error code from the API error body. */
  public readonly errorCode: string | undefined;

  constructor(
    operation: string,
    message: string,
    statusCode?: number,
    errorCode?: string,
    cause?: Error,
  ) {
    super(`Relayer operation '${operation}' failed: ${message}`);
    this.name = "RelayerError";
    this.operation = operation;
    this.statusCode = statusCode;
    this.errorCode = errorCode;
    this.cause = cause;

    if (Error.captureStackTrace !== undefined) {
      Error.captureStackTrace(this, RelayerError);
    }
  }
}

// ============================================================================
// Internal Types (API Response Shapes)
// ============================================================================

/** @internal */
interface ApiErrorResponse {
  error?: {
    code: string;
    message: string;
  };
  success?: false;
  error_code?: string;
  message?: string;
}

/** Shape of `GET /v1/relayer/info` response. @internal */
interface ApiRelayerInfoResponse {
  address: string;
  supported_mints: string[];
  active_stealth_pool_indices: string[];
}

/** Shape of `POST /v1/claims` response. @internal */
interface ApiClaimSubmitResponse {
  request_id: string;
  status: "received";
}

/** Shape of `GET /v1/claims/{id}` response. @internal */
interface ApiClaimStatusResponse {
  request_id: string;
  status: string;
  variant: string;
  resolved_variant?: string;
  tx_signature?: string;
  callback_signature?: string;
  computation_account?: string;
  failure_reason?: string | null;
  created_at: string;
  updated_at: string;
}

// ============================================================================
// Internal Helpers
// ============================================================================

/**
 * Generic HTTP request helper with structured error handling.
 * @internal
 */
async function makeRequest<T>(
  endpoint: string,
  fetchImpl: typeof globalThis.fetch,
  options: {
    method?: "GET" | "POST";
    body?: unknown;
    operation: string;
  },
): Promise<T> {
  const { method = "GET", body, operation } = options;

  try {
    const requestInit: RequestInit = {
      method,
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
      },
    };
    if (body !== undefined) {
      requestInit.body = JSON.stringify(body);
    }
    const response = await fetchImpl(endpoint, requestInit);

    const data = (await response.json()) as T | ApiErrorResponse;

    if (!response.ok) {
      const errorData = data as ApiErrorResponse;
      const message =
        errorData.error?.message ?? errorData.message ?? `HTTP ${String(response.status)}`;
      const code = errorData.error?.code ?? errorData.error_code;
      throw new RelayerError(operation, message, response.status, code);
    }

    return data as T;
  } catch (error) {
    if (error instanceof RelayerError) {
      throw error;
    }
    throw new RelayerError(
      operation,
      error instanceof Error ? error.message : "Unknown error",
      undefined,
      undefined,
      error instanceof Error ? error : undefined,
    );
  }
}

/** Converts wire-format claim status response to SDK type. @internal */
function convertClaimStatusResponse(api: ApiClaimStatusResponse): ClaimStatusResponse {
  return {
    requestId: api.request_id,
    status: api.status as ClaimStatus,
    variant: api.variant as ClaimStatusResponse["variant"],
    resolvedVariant: api.resolved_variant,
    txSignature: api.tx_signature,
    callbackSignature: api.callback_signature,
    computationAccount: api.computation_account,
    failureReason: api.failure_reason,
    createdAt: api.created_at,
    updatedAt: api.updated_at,
  };
}

// ============================================================================
// Core Relayer Factory
// ============================================================================

/**
 * Creates an Umbra relayer instance.
 *
 * @remarks
 * The returned `IUmbraRelayer` object provides all methods needed by claim
 * services: relayer info, claim submission, and status polling. Pass it
 * directly as the `relayer` dependency to any claim function.
 *
 * **Address caching:**
 * `getRelayerAddress()` and `getFeePayer()` cache the result after the first
 * HTTP call. The cache is per-instance.
 *
 * @param args - Required arguments
 * @param args.apiEndpoint - The base URL of the relayer API
 * @param deps - Optional dependencies for testing
 * @param deps.fetch - Custom fetch implementation; defaults to `globalThis.fetch`
 * @returns An {@link IUmbraRelayer} instance
 *
 * @example
 * ```typescript
 * const relayer = getUmbraRelayer({ apiEndpoint: "https://relayer.umbra.finance" });
 *
 * // Use directly with claim functions
 * const claim = getSelfClaimableUtxoToEncryptedBalanceClaimerFunction(
 *   { client },
 *   { zkProver, relayer },
 * );
 * ```
 *
 * @public
 */
export function getUmbraRelayer(
  args: GetUmbraRelayerArgs,
  deps?: GetUmbraRelayerDeps,
): IUmbraRelayer {
  const { apiEndpoint } = args;
  const fetchImpl = deps?.fetch ?? globalThis.fetch;

  if (apiEndpoint === "") {
    throw new RelayerError("initialization", "apiEndpoint must be a non-empty string");
  }

  const normalizedEndpoint = apiEndpoint.replace(/\/$/, "");

  // Shared cache for relayer address (used by both getFeePayer and getRelayerAddress)
  let cachedAddress: Address | null = null;
  let cachedInfo: ApiRelayerInfoResponse | null = null;

  async function fetchInfo(): Promise<ApiRelayerInfoResponse> {
    if (cachedInfo !== null) {
      return cachedInfo;
    }
    const response = await makeRequest<ApiRelayerInfoResponse>(
      `${normalizedEndpoint}${ENDPOINTS.RELAYER_INFO}`,
      fetchImpl,
      { operation: "getRelayerInfo" },
    );
    cachedInfo = response;
    cachedAddress = address(response.address);
    return response;
  }

  return {
    apiEndpoint: normalizedEndpoint,

    async getFeePayer(): Promise<Address> {
      if (cachedAddress !== null) {
        return cachedAddress;
      }
      const info = await fetchInfo();
      return address(info.address);
    },

    async getRelayerAddress(): Promise<Address> {
      if (cachedAddress !== null) {
        return cachedAddress;
      }
      const info = await fetchInfo();
      return address(info.address);
    },

    async getSupportedMints(): Promise<SupportedMintsResponse> {
      const info = await fetchInfo();
      return {
        relayer: info.address,
        mints: info.supported_mints,
        count: BigInt(info.supported_mints.length) as U32,
      };
    },

    async submitClaim(request: ClaimRequest): Promise<ClaimSubmitResponse> {
      const response = await makeRequest<ApiClaimSubmitResponse>(
        `${normalizedEndpoint}${ENDPOINTS.CLAIM_SUBMIT}`,
        fetchImpl,
        { method: "POST", body: request, operation: "claimSubmit" },
      );
      return {
        requestId: response.request_id,
        status: response.status,
      };
    },

    async pollClaimStatus(requestId: string): Promise<ClaimStatusResponse> {
      const url = `${normalizedEndpoint}${ENDPOINTS.CLAIM_STATUS.replace("{id}", requestId)}`;
      const response = await makeRequest<ApiClaimStatusResponse>(url, fetchImpl, {
        operation: "claimStatus",
      });
      return convertClaimStatusResponse(response);
    },
  };
}

// ============================================================================
// Claim Polling Utility
// ============================================================================

/**
 * Terminal claim statuses. Polling stops when the status matches one of these.
 * @internal
 */
const TERMINAL_CLAIM_STATUSES: ReadonlySet<ClaimStatus> = new Set([
  "completed",
  "failed",
  "timed_out",
]);

/**
 * Polls a claim request until it reaches a terminal status or times out.
 *
 * @remarks
 * Terminal statuses are: `completed`, `failed`, `timed_out`.
 * The `onProgress` callback is invoked after each poll with the latest status.
 *
 * @param pollClaimStatus - Function to poll claim status
 * @param requestId - The claim request ID to poll
 * @param options - Polling configuration
 * @returns The final {@link ClaimBatchResult}
 *
 * @public
 */
export async function pollClaimUntilTerminal(
  pollClaimStatus: (requestId: string) => Promise<ClaimStatusResponse>,
  requestId: string,
  options?: {
    pollingIntervalMs?: number;
    timeoutMs?: number;
    onProgress?: (event: {
      readonly requestId: string;
      readonly status: ClaimStatus;
      readonly resolvedVariant?: string;
      readonly txSignature?: string;
      readonly callbackSignature?: string;
      readonly failureReason?: string | null;
    }) => void;
  },
): Promise<ClaimBatchResult> {
  const pollingIntervalMs: number = options?.pollingIntervalMs ?? 3000;
  const timeoutMs: number = options?.timeoutMs ?? 120_000;
  const onProgress = options?.onProgress;

  const startTime: number = Date.now();

  // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition -- polling loop
  while (true) {
    const status: ClaimStatusResponse = await pollClaimStatus(requestId);

    if (onProgress !== undefined) {
      onProgress({
        requestId: status.requestId,
        status: status.status,
        resolvedVariant: status.resolvedVariant,
        txSignature: status.txSignature,
        callbackSignature: status.callbackSignature,
        failureReason: status.failureReason,
      });
    }

    if (TERMINAL_CLAIM_STATUSES.has(status.status)) {
      const result: ClaimBatchResult = {
        requestId: status.requestId,
        status: status.status,
        txSignature: status.txSignature,
        callbackSignature: status.callbackSignature,
        resolvedVariant: status.resolvedVariant,
        failureReason: status.failureReason,
      };
      return result;
    }

    if (Date.now() - startTime >= timeoutMs) {
      const timedOutResult: ClaimBatchResult = {
        requestId: status.requestId,
        status: "timed_out" as ClaimStatus,
        failureReason: `Polling timed out after ${String(timeoutMs)}ms (last status: ${String(status.status)})`,
      };
      return timedOutResult;
    }

    await new Promise<void>((resolve) => {
      setTimeout(resolve, pollingIntervalMs);
    });
  }
}
